-- CommandProject: cheats for playing alone (generated by the launcher).
-- They apply to the human player (and to the AI if chosen). With more than one human in the match
-- (multiplayer) nothing is turned on and the in-game menu commands are ignored.
local State = {
    Mass = @MASS@,
    Energy = @ENERGY@,
    Research = @RESEARCH@,
    God = @GOD@,
    BuildSpeed = @SPEED@,
    AiToo = @AI@,
}
local UNLOCK_AT_START = @UNLOCK@
local FULL = 100000
local Active = false

local function IsCivilian(brain)
    local civ = false
    pcall(function() civ = ArmyIsCivilian(brain:GetArmyIndex()) end)
    return civ
end

local function Cheating(brain)
    return brain.BrainType == 'Human' or State.AiToo
end

local function Fill(brain, kind, target)
    -- room in storage first (the game caps mass and energy to the storage size)
    pcall(function() brain:SetMaxStorage(kind, target + 1000) end)
    local stored = 0
    pcall(function() stored = brain:GetEconomyStored(kind) end)
    if stored < target then
        pcall(function() brain:GiveResource(kind, target - stored) end)
    end
end

local function UnlockAll()
    for _, brain in ArmyBrains do
        if not IsCivilian(brain) and Cheating(brain) then
            local idx = brain:GetArmyIndex()
            if not pcall(function() UnlockAllResearch(idx) end) then
                pcall(function() brain:AddAllResearch() end)
            end
        end
    end
end

local function SetGod(unit, on)
    if on and not unit.CPGod then
        unit.CPGod = { unit.CanTakeDamage, unit.CanBeKilled }
        pcall(function() unit:SetCanTakeDamage(false) end)
        pcall(function() unit:SetCanBeKilled(false) end)
    elseif not on and unit.CPGod then
        local orig = unit.CPGod
        unit.CPGod = nil
        pcall(function() unit:SetCanTakeDamage(orig[1] ~= false) end)
        pcall(function() unit:SetCanBeKilled(orig[2] ~= false) end)
    end
end

-- research changes the build rate too: when the game changes it we take the new value as the base
local function SetSpeed(unit, mult)
    if mult <= 1 and not unit.CPBase then return end
    local now = 0
    pcall(function() now = unit:GetBuildRate() end)
    if not now or now <= 0 then return end
    if not unit.CPSet or math.abs(now - unit.CPSet) > 0.001 then
        unit.CPBase = now
    end
    if mult <= 1 then
        local base = unit.CPBase
        unit.CPBase = nil
        unit.CPSet = nil
        pcall(function() unit:SetBuildRate(base) end)
        return
    end
    local want = unit.CPBase * mult
    if math.abs(now - want) > 0.001 then
        pcall(function() unit:SetBuildRate(want) end)
    end
    unit.CPSet = want
end

local function Tick()
    for _, brain in ArmyBrains do
        if not IsCivilian(brain) and not brain:IsDefeated() then
            local on = Cheating(brain)
            if on and State.Mass then Fill(brain, 'MASS', FULL) end
            if on and State.Energy then Fill(brain, 'ENERGY', FULL) end
            if on and State.Research then
                -- matches with a research cap lock the storage after each technology
                if brain.CPCapped == nil then brain.CPCapped = brain.ResearchCapped or false end
                brain.ResearchCapped = false
                Fill(brain, 'RESEARCH', FULL - 1)
            elseif brain.CPCapped ~= nil then
                brain.ResearchCapped = brain.CPCapped
                brain.CPCapped = nil
            end
            local god = on and State.God
            local mult = 1
            if on then mult = State.BuildSpeed end
            if god or mult > 1 or brain.CPTouched then
                brain.CPTouched = god or mult > 1
                local list = {}
                pcall(function() list = brain:GetListOfUnits(categories.ALLUNITS, false) end)
                for _, unit in list do
                    if unit and not unit:IsDead() then
                        SetGod(unit, god)
                        SetSpeed(unit, mult)
                    end
                end
            end
        end
    end
end

-- called by the in-game menu (SimCallback 'CPCheats')
function Set(data)
    if not Active or type(data) ~= 'table' then return end
    for _, key in { 'Mass', 'Energy', 'Research', 'God', 'AiToo' } do
        if type(data[key]) == 'boolean' then State[key] = data[key] end
    end
    if type(data.BuildSpeed) == 'number' then
        State.BuildSpeed = math.max(1, math.min(50, data.BuildSpeed))
    end
    if data.UnlockNow == true then UnlockAll() end
    Tick()
end

function Run()
    WaitSeconds(1)
    local humans = 0
    for _, brain in ArmyBrains do
        if not IsCivilian(brain) and brain.BrainType == 'Human' then humans = humans + 1 end
    end
    if humans > 1 then
        LOG('*CommandProject: cheats off (more than one human player)')
        return
    end
    Active = true
    LOG('*CommandProject: cheats on')
    if UNLOCK_AT_START then UnlockAll() end
    while true do
        Tick()
        WaitSeconds(1)
    end
end
